package com.hamza.streetsovereign;
import android.content.*;import android.graphics.*;import android.media.*;import android.speech.tts.*;import android.view.*;import java.util.*;

public class GameView extends View{
 Paint p=new Paint(3);Random r=new Random(9);ToneGenerator tone=new ToneGenerator(AudioManager.STREAM_MUSIC,85);TextToSpeech voice;
 int W,H,cash=12500,hp=100,wanted=0,mission=0,quality=2;float x=.5f,y=.55f,jx,jy,heat,clock=18;boolean menu=true,paused=false,car=false,fire=false;
 ArrayList<V> cars=new ArrayList<>(),people=new ArrayList<>();String[] M={"SUNSET RUN","NEON PACKAGE","RIVER DISTRICT","HIGHWAY HEAT","NIGHT WOLVES","CITY TAKEOVER"};
 public GameView(Context c){super(c);setFocusable(true);voice=new TextToSpeech(c,z->{if(z==0)voice.setLanguage(Locale.US);});for(int i=0;i<35;i++)cars.add(new V(r.nextFloat(),.2f+r.nextFloat()*.7f,i%6,false));for(int i=0;i<55;i++)people.add(new V(r.nextFloat(),.18f+r.nextFloat()*.75f,0,i%8==0));}
 void say(String s){if(voice!=null)voice.speak(s,TextToSpeech.QUEUE_FLUSH,null,"ss");}
 protected void onDraw(Canvas c){W=getWidth();H=getHeight();if(menu){menu(c);return;}drawWorld(c);if(paused)pause(c);else{update();postInvalidateDelayed(16);}}
 void update(){float d=.016f;clock=(clock+d*.08f)%24;x=Math.max(.03f,Math.min(.97f,x+jx*d*(car?.34f:.22f)));y=Math.max(.17f,Math.min(.94f,y+jy*d*(car?.34f:.22f)));heat=Math.max(0,heat-d*2);if(heat<5)wanted=0;if(fire){for(V q:people)if(!q.dead&&Math.hypot(q.x-x,q.y-y)<.11){q.hp-=50*d;if(q.hp<1){q.dead=true;cash+=200;}}}for(V q:people)if(q.cop&&!q.dead&&Math.hypot(q.x-x,q.y-y)<.28){hp-=1;wanted=2;heat=60;q.x+=(x-q.x)*d*.04f;q.y+=(y-q.y)*d*.04f;}float tx=.8f,ty=.25f+(mission*.1f)%0.6f;if(Math.hypot(x-tx,y-ty)<.07f){cash+=1000+mission*500;mission=(mission+1)%6;wanted=Math.max(0,wanted-1);say("Mission complete. "+M[mission]);tone.startTone(ToneGenerator.TONE_PROP_ACK,160);}}
 void drawWorld(Canvas c){float night=(float)((Math.sin(clock/24*6.283)+1)/2);p.setColor(Color.rgb((int)(25+25*night),(int)(45+15*night),(45+30)));c.drawRect(0,0,W,H,p);
  p.setColor(Color.rgb(30,70,60));c.drawRect(0,H*.14f,W,H,p);p.setColor(Color.rgb(10,45,70));c.drawRect(0,0,W,H*.14f,p);
  p.setColor(Color.rgb(40,42,46));for(int i=0;i<7;i++)c.drawRect(i*W/7f,H*.14f,i*W/7f+W*.055f,H,p);for(int i=0;i<7;i++)c.drawRect(0,H*(.2f+i*.11f),W,H*(.2f+i*.11f)+H*.035f,p);
  p.setColor(Color.rgb(225,190,70));for(int i=0;i<45;i++){float a=(i%10)*W*.105f+20,b=H*(.215f+(i/10)*.11f);c.drawRect(a,b,a+W*.045f,b+4,p);}
  for(int i=0;i<110;i++){float a=(i*79%W),b=H*(.16f+(i*43%78)/100f),w=22+(i%6)*12,h=30+(i%7)*16;p.setColor(Color.rgb(55+i%4*16,58+i%3*14,68+i%5*9));c.drawRect(a,b,a+w,b+h,p);p.setColor(Color.argb(180,245,210,100));c.drawRect(a+6,b+7,a+12,b+13,p);}
  p.setColor(Color.argb(100,255,30,140));c.drawRect(W*.58f,H*.16f,W*.98f,H*.43f,p);txt(c,"VICE RAY",W*.67f,H*.25f,24,Color.WHITE);txt(c,"RIVERDALE",W*.08f,H*.76f,22,Color.WHITE);txt(c,"SAN VALORA",W*.72f,H*.82f,22,Color.WHITE);
  for(V q:cars)car(c,q.x*W,q.y*H,q.n);for(V q:people)if(!q.dead){p.setColor(q.cop?Color.rgb(50,105,230):Color.rgb(220,160,90));c.drawCircle(q.x*W,q.y*H,11,p);}
  p.setColor(Color.WHITE);c.drawCircle(x*W,y*H,car?19:15,p);p.setColor(Color.DKGRAY);c.drawCircle(x*W,y*H-4,5,p);
  p.setColor(Color.argb(210,0,0,0));c.drawRoundRect(16,14,450,130,18,18,p);txt(c,"STREET SOVEREIGN",32,45,21,Color.WHITE);txt(c,"HAMZA",32,75,26,Color.rgb(255,70,55));txt(c,"$"+cash,32,106,20,Color.WHITE);bar(c,160,56,405,72,hp,Color.GREEN);
  txt(c,M[mission],W/2-90,42,20,Color.WHITE);txt(c,"OBJECTIVE "+(mission+1)+"/6",W/2-90,67,14,Color.LTGRAY);if(wanted>0)txt(c,"WANTED  "+"★★★★★".substring(0,Math.min(5,wanted)),W-215,42,18,Color.YELLOW);
  p.setColor(Color.argb(150,0,0,0));c.drawCircle(105,H-100,76,p);p.setColor(Color.argb(200,255,255,255));c.drawCircle(105+jx*40,H-100+jy*40,26,p);btn(c,W-110,H-100,60,"FIRE");btn(c,W-225,H-100,52,car?"EXIT":"CAR");btn(c,W-340,H-100,48,"MAP");btn(c,W-455,H-100,48,"PAUSE");
 }
 void bar(Canvas c,float a,float b,float d,float e,int v,int col){p.setColor(Color.DKGRAY);c.drawRoundRect(a,b,d,e,7,7,p);p.setColor(col);c.drawRoundRect(a,b,a+(d-a)*v/100f,e,7,7,p);}
 void car(Canvas c,float a,float b,int n){int[] z={Color.RED,Color.BLUE,Color.YELLOW,Color.GREEN,Color.MAGENTA,Color.WHITE};p.setColor(z[n%6]);c.drawRoundRect(a-28,b-14,a+28,b+14,8,8,p);p.setColor(Color.DKGRAY);c.drawRect(a-13,b-9,a+13,b+9,p);p.setColor(Color.WHITE);c.drawCircle(a-19,b-14,4,p);c.drawCircle(a+19,b-14,4,p);c.drawCircle(a-19,b+14,4,p);c.drawCircle(a+19,b+14,4,p);}
 void btn(Canvas c,float a,float b,float r,String s){p.setColor(Color.argb(130,0,0,0));c.drawCircle(a,b,r,p);txt(c,s,a-p.measureText(s)/2,b+5,14,Color.WHITE);}
 void menu(Canvas c){p.setColor(Color.rgb(8,10,18));c.drawRect(0,0,W,H,p);for(int i=0;i<80;i++){p.setColor(Color.rgb(20+i%5*12,20+i%4*10,40+i%6*12));c.drawRect(0,H*.18f+i*H*.01f,W,H*.19f+i*H*.01f,p);}txt(c,"STREET",W*.09f,H*.24f,72,Color.WHITE);txt(c,"SOVEREIGN",W*.09f,H*.34f,72,Color.WHITE);txt(c,"HAMZA",W*.095f,H*.43f,60,Color.rgb(255,70,55));txt(c,"TRILOGY EDITION",W*.10f,H*.48f,22,Color.LTGRAY);p.setColor(Color.WHITE);c.drawRoundRect(W*.1f,H*.58f,W*.37f,H*.73f,22,22,p);txt(c,"PLAY",W*.2f,H*.67f,34,Color.BLACK);p.setColor(Color.argb(210,0,0,0));c.drawRoundRect(W*.42f,H*.52f,W*.92f,H*.8f,22,22,p);txt(c,"THREE CITIES • ONE WORLD",W*.46f,H*.58f,21,Color.WHITE);txt(c,"• story missions + free roam",W*.46f,H*.63f,17,Color.LTGRAY);txt(c,"• cars • police • gangs • combat",W*.46f,H*.675f,17,Color.LTGRAY);txt(c,"• day/night • voice • graphics",W*.46f,H*.72f,17,Color.LTGRAY);txt(c,"• offline single-player",W*.46f,H*.765f,17,Color.LTGRAY);}
 void pause(Canvas c){p.setColor(Color.argb(220,0,0,0));c.drawRect(0,0,W,H,p);txt(c,"GRAPHICS SETTINGS",W/2-145,H*.25f,30,Color.WHITE);btn(c,W/2-100,H*.43f,58,"LOW");btn(c,W/2,H*.43f,58,"MED");btn(c,W/2+100,H*.43f,58,"ULTRA");btn(c,W/2,H*.62f,70,"RESUME");txt(c,"VOICE + AUDIO ON",W/2-90,H*.75f,16,Color.WHITE);}
 boolean hit(float a,float b,float c,float d,float rr){return Math.hypot(a-c,b-d)<rr;}
 public boolean onTouchEvent(MotionEvent e){float a=e.getX(),b=e.getY();int k=e.getActionMasked();if(menu){if(k==0&&a>W*.08f&&a<W*.42f&&b>H*.52f&&b<H*.77f){menu=false;say("Welcome to Street Sovereign. Three cities. One empire.");}return true;}if(k==0||k==2){if(a<250&&b>H-220){jx=(a-105)/75f;jy=(b-H+100)/75f;float l=(float)Math.hypot(jx,jy);if(l>1){jx/=l;jy/=l;}}if(hit(a,b,W-110,H-100,70)){fire=true;wanted=Math.max(1,wanted);heat=Math.min(100,heat+22);tone.startTone(ToneGenerator.TONE_PROP_BEEP,50);}}if(k==1){if(a<250&&b>H-220)jx=jy=0;if(hit(a,b,W-225,H-100,65))car=!car;if(hit(a,b,W-455,H-100,60))paused=true;if(paused&&hit(a,b,W/2-100,H*.43f,65))quality=0;if(paused&&hit(a,b,W/2,H*.43f,65))quality=1;if(paused&&hit(a,b,W/2+100,H*.43f,65))quality=2;if(paused&&hit(a,b,W/2,H*.62f,80))paused=false;fire=false;}return true;}
 void txt(Canvas c,String s,float a,float b,float z,int col){p.setColor(col);p.setTextSize(z);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(s,a,b,p);}
 protected void onDetachedFromWindow(){if(voice!=null){voice.stop();voice.shutdown();}tone.release();super.onDetachedFromWindow();}
 static class V{float x,y,hp=100;int n;boolean cop,dead;V(float x,float y,int n,boolean cop){this.x=x;this.y=y;this.n=n;this.cop=cop;}}
}